import{_ as t,o as a,c as i,l as o,t as s,N as n}from"./chunks/framework.Gjrf2Eoj.js";const b=JSON.parse('{"title":"git-show-index | x-cmd man (git man1) | Show packed archive index","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-show-index - Show packed archive index","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-show-index | x-cmd man (git man1) | Show packed archive index"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-show-index - Show packed archive index"}]]},"headers":[],"params":{"isMan":true,"man":"git-show-index","category":"git man1","desc":"Show packed archive index"},"relativePath":"git/man1/git-show-index.md","filePath":"git/man1/git-show-index.md"}'),r={name:"git/man1/git-show-index.md"},h={class:"visually-hidden"},c=n('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-show-index - Show packed archive index</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show-index</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--object-format=&lt;hash-algorithm&gt;]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Read the <strong>.idx</strong> file for a Git packfile (created with <strong>git-pack-objects</strong>(1) or <strong>git-index-pack</strong>(1)) from the standard input, and dump its contents. The output consists of one object per line, with each line containing two or three space-separated columns:</p><blockquote><p>·</p><p>the first column is the offset in bytes of the object within the corresponding packfile</p></blockquote><blockquote><p>·</p><p>the second column is the object id of the object</p></blockquote><blockquote><p>·</p><p>if the index version is 2 or higher, the third column contains the CRC32 of the object data</p></blockquote><p>The objects are output in the order in which they are found in the index file, which should be (in a correctly constructed file) sorted by object id.</p><p>Note that you can get more information on a packfile by calling <strong>git-verify-pack</strong>(1). However, as this command considers only the index file itself, it&#39;s both faster and more flexible.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>--object-format=&lt;hash-algorithm&gt;</p><blockquote><p>Specify the given object format (hash algorithm) for the index file. The valid values are <em>sha1</em> and (if enabled) <em>sha256</em>. The default is the algorithm for the current repository (set by <strong>extensions.objectFormat</strong>), or <em>sha1</em> if no value is set or outside a repository..</p><p>THIS OPTION IS EXPERIMENTAL! SHA-256 support is experimental and still in an early stage. A SHA-256 repository will in general not be able to share work with &quot;regular&quot; SHA-1 repositories. It should be assumed that, e.g., Git internal file formats in relation to SHA-256 repositories may change in backwards-incompatible ways. Only use <strong>--object-format=sha256</strong> for testing purposes.</p></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>',16);function l(e,d,p,m,g,u){return a(),i("div",null,[o("h1",h,s(e.$params.man),1),c])}const k=t(r,[["render",l]]);export{b as __pageData,k as default};
